const response = $json;
const isHttpOk = !response.error && (response.status === 'pass' || response.status === 'warn');
const isHealthy = Boolean(response.healthy) && isHttpOk;

const dbStatus = response.services?.database?.status || 'fail';
const cacheStatus = response.services?.cache?.status || 'fail';
const heapUsedMb = response.services?.system?.heapUsedMb || 0;
const latencyMs = response.latencyMs || 0;
const uptimeHours = response.uptimeSeconds ? (response.uptimeSeconds / 3600).toFixed(2) : '0';

const isDbFailing = dbStatus !== 'pass';
const isCacheFailing = cacheStatus === 'fail';
const isRamCritical = heapUsedMb > 950;
const isLatencyCritical = latencyMs > 3500;

const hasIssue = !isHealthy || isDbFailing || isCacheFailing || isRamCritical || isLatencyCritical;

let severity = 'OK';
let reason = 'Tüm servisler operasyonel.';
if (!isHealthy) {
  severity = 'CRITICAL';
  reason = 'Web uygulaması (/api/health) yanıt vermiyor veya FAIL durumunda!';
} else if (isDbFailing) {
  severity = 'CRITICAL';
  reason = 'PostgreSQL veritabanı bağlantısı koptu!';
} else if (isRamCritical) {
  severity = 'WARNING';
  reason = `Node.js RAM tüketimi kritik eşiği aştı: ${heapUsedMb} MB`;
} else if (isLatencyCritical) {
  severity = 'WARNING';
  reason = `Sistem gecikmesi çok yüksek: ${latencyMs} ms`;
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    hasIssue,
    severity,
    reason,
    dbStatus,
    cacheStatus,
    heapUsedMb,
    latencyMs,
    uptimeHours
  }
}];

const secondCheck = $json;
const isSecondOk = !secondCheck.error && (secondCheck.status === 'pass' || secondCheck.status === 'warn');
const isSecondHealthy = Boolean(secondCheck.healthy) && isSecondOk;

// Eğer 2. kontrolde düzelmişse bu geçici bir dalgalanmadır (flapping), alarm çalma
const isConfirmedIncident = !isSecondHealthy;

return [{
  json: {
    isConfirmedIncident,
    severity: isConfirmedIncident ? 'CRITICAL' : 'RECOVERED_TRANSIENT',
    reason: isConfirmedIncident ? 'Arka arkaya yapılan 2 kontrolde de servis yanıt vermedi!' : 'Geçici gecikme tespit edildi, 2. denemede servis toparlandı.',
    timestamp: new Date().toISOString(),
    secondCheck
  }
}];

const incident = $json;
console.error('🚨 [KRİTİK KESİNTİ ALARMI]', incident);
return [{ json: { success: true, alertSent: true, recipient: 'istanbul@aloyonetim.com.tr', incident } }];
